using Microsoft.AspNetCore.Mvc.ModelBinding; namespace ApiFromLecture.Binders; public class CsvIntArrayBinder:IModelBinder { public Task BindModelAsync(ModelBindingContext c){var raw=c.ValueProvider.GetValue(c.ModelName).FirstValue;if(string.IsNullOrEmpty(raw)){c.Result=ModelBindingResult.Failed();return Task.CompletedTask;} try{c.Result=ModelBindingResult.Success(raw.Split(',',StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray());}catch(FormatException){c.ModelState.AddModelError(c.ModelName,"Ids должны быть целыми числами, разделёнными запятыми.");c.Result=ModelBindingResult.Failed();}return Task.CompletedTask;} }
